package clickhouse

func (s *connSuite) TestExecBuild19() {
	testCases := []struct {
		query  string
		query2 string
		args   []interface{}
	}{
		{
			"INSERT INTO data (u64) VALUES (?)",
			"SELECT u64 FROM data WHERE u64=?",
			[]interface{}{uint64(maxAllowedUInt64 - 1)},
		},
		{
			"INSERT INTO data (u64) VALUES (?)",
			"SELECT u64 FROM data WHERE u64=?",
			[]interface{}{uint64(maxAllowedUInt64 * 2)},
		},
	}
	for _, tc := range testCases {
		result, err := s.conn.Exec(tc.query, tc.args...)
		if !s.NoError(err) {
			continue
		}
		s.NotNil(result)
		_, err = result.LastInsertId()
		s.Equal(ErrNoLastInsertID, err)
		_, err = result.RowsAffected()
		s.Equal(ErrNoRowsAffected, err)
		if len(tc.query2) == 0 {
			continue
		}
		rows, err := s.conn.Query(tc.query2, tc.args...)
		if !s.NoError(err) {
			continue
		}
		v, err := scanValues(rows, tc.args)
		if s.NoError(err) {
			s.Equal([][]interface{}{tc.args}, v)
		}
		s.NoError(rows.Close())
	}
}

func (s *connSuite) TestQuotedStrings() {
	testCases := []struct {
		query, expected1, expected2 string
	}{
		{
			`SELECT '"foo" foo', 'bar'`, `"foo" foo`, "bar",
		},
		{
			`SELECT 'bar', '"foo" foo'`, "bar", `"foo" foo`,
		},
	}
	for _, tc := range testCases {
		var actual1, actual2 string
		err := s.conn.QueryRow(tc.query).Scan(&actual1, &actual2)
		if !s.NoError(err) {
			continue
		}
		s.Equal(tc.expected1, actual1)
		s.Equal(tc.expected2, actual2)
	}
}

package clickhouse

import (
	"database/sql/driver"
	"net"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

func TestArray(t *testing.T) {
	testCases := []struct {
		value    interface{}
		expected driver.Value
	}{
		{[]int16{1, 2}, []byte("[1,2]")},
		{[]int32{1, 2}, []byte("[1,2]")},
		{[]int64{1, 2}, []byte("[1,2]")},
		{[]uint16{1, 2}, []byte("[1,2]")},
		{[]uint32{1, 2}, []byte("[1,2]")},
		{[]uint64{1, 2}, []byte("[1,2]")},
		{[]uint64{}, []byte("[]")},
	}

	for _, tc := range testCases {
		dv, err := Array(tc.value).Value()
		if assert.NoError(t, err) {
			assert.Equal(t, tc.expected, dv)
		}
	}
}

func TestDate(t *testing.T) {
	d := time.Date(2016, 4, 4, 0, 0, 0, 0, time.Local)
	dv, err := Date(d).Value()
	if assert.NoError(t, err) {
		assert.Equal(t, []byte("'2016-04-04'"), dv)
	}
}

func TestUInt64(t *testing.T) {
	u := uint64(1) << 63
	dv, err := UInt64(u).Value()
	if assert.NoError(t, err) {
		assert.Equal(t, []byte("9223372036854775808"), dv)
	}
}

func TestDecimal(t *testing.T) {
	dv, err := Decimal32("1000", 4).Value()
	if assert.NoError(t, err) {
		assert.Equal(t, []byte("toDecimal32('1000', 4)"), dv)
	}

	dv, err = Decimal64(100, 1).Value()
	if assert.NoError(t, err) {
		assert.Equal(t, []byte("toDecimal64('100', 1)"), dv)
	}
	dv, err = Decimal128(100.01, 1).Value()
	if assert.NoError(t, err) {
		assert.Equal(t, []byte("toDecimal128('100.01', 1)"), dv)
	}
}

func TestIP(t *testing.T) {
	ipv4 := net.ParseIP("127.0.0.1")
	assert.NotNil(t, ipv4)
	ipv6 := net.ParseIP("2001:44c8:129:2632:33:0:252:2")
	assert.NotNil(t, ipv6)
	dv, err := IP(ipv4).Value()
	assert.NoError(t, err)
	assert.Equal(t, "127.0.0.1", dv)
	dv, err = IP(ipv6).Value()
	assert.NoError(t, err)
	assert.Equal(t, "2001:44c8:129:2632:33:0:252:2", dv)
}

package clickhouse

import (
	"database/sql/driver"
	"math"
	"reflect"
	"testing"

	"github.com/stretchr/testify/assert"
)

func getUInt64Ptr(v uint64) *uint64 {
	return &v
}

func TestConverter(t *testing.T) {
	testCases := []struct {
		value    interface{}
		expected driver.Value
		msg      string
	}{
		// uint64
		{getUInt64Ptr(0), uint64(0), "*uint64(0)"},
		{getUInt64Ptr(maxAllowedUInt64), uint64(9223372036854775807), "*uint64(maxAllowedUInt64)"},
		{getUInt64Ptr(maxAllowedUInt64 + 1), []byte("9223372036854775808"), "*uint64(maxAllowedUInt64+1)"},
		{getUInt64Ptr(maxAllowedUInt64*2 + 1), []byte("18446744073709551615"), "*uint64(maxUInt64)"},

		// int64
		{int64(0), int64(0), "int64(0)"},
		{int64(math.MinInt64), int64(-9223372036854775808), "int64(MinInt64)"},
		{int64(math.MaxInt64), int64(9223372036854775807), "int64(MaxInt64)"},
		// uint64
		{uint64(0), uint64(0), "uint64(0)"},
		{uint64(maxAllowedUInt64), uint64(9223372036854775807), "uint64(maxAllowedUInt64)"},
		{uint64(maxAllowedUInt64 + 1), []byte("9223372036854775808"), "uint64(maxAllowedUInt64+1)"},
		{uint64(maxAllowedUInt64*2 + 1), []byte("18446744073709551615"), "uint64(maxUInt64)"},
	}

	for _, tc := range testCases {
		dv, err := converter{}.ConvertValue(tc.value)
		if assert.NoError(t, err) {
			// assert.ElementsMatch(t, dv, tc.expected, "failed to convert "+tc.msg)
			if !reflect.DeepEqual(tc.expected, dv) {
				t.Errorf("failed to convert %s", tc.msg)
			}
		}
	}
}

package clickhouse

import (
	"regexp"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

type TestEmbedTuple struct {
	C       bool
	private int
}

type TestTuple struct {
	A int
	B string
	TestEmbedTuple
}

type TestNestedTuple struct {
	A *TestTuple
	D int
}

func TestTextEncoder(t *testing.T) {
	dt := time.Date(2011, 3, 6, 6, 20, 0, 0, time.UTC)
	d := time.Date(2012, 5, 31, 0, 0, 0, 0, time.UTC)
	testCases := []struct {
		value    interface{}
		expected string
	}{
		{true, "1"},
		{int8(1), "1"},
		{int16(1), "1"},
		{int32(1), "1"},
		{int64(1), "1"},
		{int(-1), "-1"},
		{uint8(1), "1"},
		{uint16(1), "1"},
		{uint32(1), "1"},
		{uint64(1), "1"},
		{uint(1), "1"},
		{float32(1), "1"},
		{float64(1), "1"},
		{dt, "'2011-03-06 06:20:00'"},
		{d, "'2012-05-31 00:00:00'"},
		{"hello", "'hello'"},
		{[]byte("hello"), "hello"},
		{`\\'hello`, `'\\\\\'hello'`},
		{[]byte(`\\'hello`), `\\'hello`},
		{[]int32{1, 2}, "[1,2]"},
		{[]int32{}, "[]"},
		{Array([]int8{1}), "[1]"},
		{Array([]interface{}{Array([]int8{1})}), "[[1]]"},
		{[][]int16{{1}}, "[[1]]"},
		{[]int16(nil), "[]"},
		{(*int16)(nil), "NULL"},
		{Tuple(TestTuple{A: 1, B: "2", TestEmbedTuple: TestEmbedTuple{C: true, private: 5}}), "(1,'2',1)"},
		{Tuple(TestNestedTuple{A: &TestTuple{A: 1, B: "2", TestEmbedTuple: TestEmbedTuple{C: true}}, D: 4}), "((1,'2',1),4)"},
		{[]TestTuple{{A: 1, B: "2", TestEmbedTuple: TestEmbedTuple{C: true, private: 5}}}, "[(1,'2',1)]"},
	}

	enc := new(textEncoder)
	for _, tc := range testCases {
		v, err := enc.Encode(tc.value)
		if assert.NoError(t, err) {
			assert.Equal(t, tc.expected, string(v))
		}
	}
}

func TestTextEncoder_Map(t *testing.T) {
	testCases := []struct {
		value interface{}
		reg   *regexp.Regexp
	}{
		{value: Map(map[string]string{"KEY1": "Value1", "Key2": "Value2"}), reg: regexp.MustCompile(`map\(('KEY1','Value1','Key2','Value2'|'Key2','Value2','KEY1','Value1')\)`)},
		{value: Map(map[string]int{"KEY1": 1, "Key2": 2}), reg: regexp.MustCompile(`map\(('KEY1',1,'Key2',2|'Key2',2,'KEY1',1)\)`)},
		{value: Map(map[string]bool{"KEY1": true, "Key2": false}), reg: regexp.MustCompile(`map\(('KEY1',1,'Key2',0|'Key2',0,'KEY1',1)\)`)},
	}

	enc := new(textEncoder)
	for _, tc := range testCases {
		v, err := enc.Encode(tc.value)
		if assert.NoError(t, err) {
			assert.True(t, tc.reg.Match(v))
		}
	}
}

package clickhouse

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
)

func Test_CtxAddTransportCallback(t *testing.T) {
	var flag bool
	ctx := context.Background()

	ctx = CtxAddTransportCallback(ctx, func(_ *http.Request, _ *http.Response) error {
		flag = true
		return nil
	})

	assert.NoError(t, callCtxTransportCallback(ctx,
		httptest.NewRequest(http.MethodGet, "http://localhost", nil), httptest.NewRecorder().Result(),
	))
	assert.True(t, flag)
}

func Test_CtxAddTransportCallback_err(t *testing.T) {
	var flag bool
	ctx := context.Background()

	ctx = CtxAddTransportCallback(ctx, func(_ *http.Request, _ *http.Response) error {
		flag = true
		return errors.New("some error")
	})

	assert.EqualError(t, callCtxTransportCallback(ctx,
		httptest.NewRequest(http.MethodGet, "http://localhost", nil), httptest.NewRecorder().Result(),
	), "some error")
	assert.True(t, flag)
}

package clickhouse

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestParseTypeDesc(t *testing.T) {
	type testCase struct {
		name   string
		input  string
		output *TypeDesc
		fail   bool
	}
	testCases := []*testCase{
		{
			name:   "plain type",
			input:  "String",
			output: &TypeDesc{Name: "String"},
		},
		{
			name:  "nullable type",
			input: "Nullable(Nothing)",
			output: &TypeDesc{
				Name: "Nullable",
				Args: []*TypeDesc{{Name: "Nothing"}},
			},
		},
		{
			name:   "empty arg",
			input:  "DateTime()",
			output: &TypeDesc{Name: "DateTime"},
		},
		{
			name:  "numeric arg",
			input: "FixedString(42)",
			output: &TypeDesc{
				Name: "FixedString",
				Args: []*TypeDesc{{Name: "42"}},
			},
		},
		{
			name:   "args are ignored for Enum",
			input:  "Enum8(you can = put, 'whatever' here)",
			output: &TypeDesc{Name: "Enum8"},
		},
		{
			name:  "quoted arg",
			input: "DateTime('UTC')",
			output: &TypeDesc{
				Name: "DateTime",
				Args: []*TypeDesc{{Name: "UTC"}},
			},
		},
		{
			name:  "decimal",
			input: "Decimal(9,4)",
			output: &TypeDesc{
				Name: "Decimal",
				Args: []*TypeDesc{{Name: "9"}, {Name: "4"}},
			},
		},
		{
			name:  "quoted escaped arg",
			input: `DateTime('UTC\b\r\n\'\f\t\0')`,
			output: &TypeDesc{
				Name: "DateTime",
				Args: []*TypeDesc{{Name: "UTC\b\r\n'\f\t\x00"}},
			},
		},
		{
			name:  "nested args",
			input: "Array(Tuple(Tuple(String, String), Tuple(String, UInt64)))",
			output: &TypeDesc{
				Name: "Array",
				Args: []*TypeDesc{
					{
						Name: "Tuple",
						Args: []*TypeDesc{
							{
								Name: "Tuple",
								Args: []*TypeDesc{{Name: "String"}, {Name: "String"}},
							},
							{
								Name: "Tuple",
								Args: []*TypeDesc{{Name: "String"}, {Name: "UInt64"}},
							},
						},
					},
				},
			},
		},
		{
			name:  "map args",
			input: "Map(String, Array(Int64))",
			output: &TypeDesc{
				Name: "Map",
				Args: []*TypeDesc{
					{
						Name: "String",
					},
					{
						Name: "Array",
						Args: []*TypeDesc{{Name: "Int64"}},
					},
				},
			},
		},
		{
			name:  "unfinished arg list",
			input: "Array(Tuple(Tuple(String, String), Tuple(String, UInt64))",
			fail:  true,
		},
		{
			name:  "left paren without name",
			input: "(",
			fail:  true,
		},
		{
			name:  "unfinished quote",
			input: "Array(')",
			fail:  true,
		},
		{
			name:  "unfinished escape",
			input: `Array(\`,
			fail:  true,
		},
		{
			name:  "stuff after end",
			input: `Array() String`,
			fail:  true,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(tt *testing.T) {
			output, err := ParseTypeDesc(tc.input)
			if tc.fail {
				assert.Error(tt, err)
			} else {
				assert.NoError(tt, err)
			}
			assert.Equal(tt, tc.output, output)
		})
	}
}

