package clickhouse

import (
	"database/sql/driver"
	"testing"

	"github.com/stretchr/testify/suite"
)

var (
	_ driver.Stmt = new(stmt)
)

type stmtSuite struct {
	chSuite
}

func (s *stmtSuite) TestQuery() {
	testCases := []struct {
		query    string
		args     [][]interface{}
		expected [][]interface{}
	}{
		{
			"SELECT i64 AS num FROM data WHERE i64=-1",
			[][]interface{}{nil, nil},
			[][]interface{}{{int64(-1)}, {int64(-1)}},
		},
		{
			"SELECT i64 AS num FROM data WHERE i64=?",
			[][]interface{}{{-2}, {-3}},
			[][]interface{}{{int64(-2)}, {int64(-3)}},
		},
		{
			"SELECT i64 AS num FROM data WHERE i64<?",
			[][]interface{}{{-3}},
			[][]interface{}{{}},
		},
	}

	for _, tc := range testCases {
		st, err := s.conn.Prepare(tc.query)
		if !s.NoError(err) {
			continue
		}
		for i, args := range tc.args {
			expected := tc.expected[i]
			rows, err := st.Query(args...)
			if !s.NoError(err) {
				continue
			}
			if len(expected) == 0 {
				s.False(rows.Next())
				s.NoError(rows.Err())
			} else {
				v, err := scanValues(rows, expected)
				if s.NoError(err) {
					s.Equal([][]interface{}{expected}, v)
				}
			}
			s.NoError(rows.Close())
		}
		s.NoError(st.Close())
		_, err = st.Query(tc.args[0]...)
		s.EqualError(err, "sql: statement is closed")
	}
}

func (s *stmtSuite) TestExec() {
	testCases := []struct {
		query  string
		query2 string
		args   [][]interface{}
	}{
		{
			"INSERT INTO data (i64) VALUES (?)",
			"SELECT i64 FROM data WHERE i64=?",
			[][]interface{}{{int64(11)}},
		},
		{
			"INSERT INTO data (i64) VALUES (?)",
			"SELECT i64 FROM data WHERE i64=?",
			[][]interface{}{{int64(12)}, {int64(13)}},
		},
	}

	for _, tc := range testCases {
		st, err := s.conn.Prepare(tc.query)
		if !s.NoError(err) {
			continue
		}
		for _, args := range tc.args {
			result, err := st.Exec(args...)
			if !s.NoError(err) {
				continue
			}
			s.NotNil(result)
			rows, err := s.conn.Query(tc.query2, args...)
			if !s.NoError(err) {
				continue
			}
			v, err := scanValues(rows, args)
			if s.NoError(err) {
				s.Equal([][]interface{}{args}, v)
			}
			s.NoError(rows.Close())
		}
		s.NoError(st.Close())
		_, err = st.Exec(tc.args[0]...)
		s.EqualError(err, "sql: statement is closed")
	}

}

func (s *stmtSuite) TestExecMulti() {
	testCases := []struct {
		insertQuery string
		exec1       int64
		exec2       int64
		query1      string
		query2      string
		expected    [][]interface{}
	}{
		{
			"INSERT INTO data (i64) VALUES (?)",
			21,
			22,
			"SELECT i64 FROM data WHERE i64=21",
			"SELECT i64 FROM data WHERE i64>20",
			[][]interface{}{{int64(21)}, {int64(22)}},
		},
		{
			"INSERT\nINTO\ndata\n(\ni64\n)\nVALUES\n(\n?\n)",
			23,
			24,
			"SELECT i64 FROM data WHERE i64=23",
			"SELECT i64 FROM data WHERE i64>22",
			[][]interface{}{{int64(23)}, {int64(24)}},
		},
	}

	for _, tc := range testCases {
		require := s.Require()
		tx, err := s.conn.Begin()
		require.NoError(err)
		st, err := tx.Prepare(tc.insertQuery)
		require.NoError(err)
		_, err = st.Exec(tc.exec1)
		require.NoError(err)
		_, err = st.Exec(tc.exec2)
		require.NoError(err)
		rows, err := s.conn.Query(tc.query1)
		require.NoError(err)
		s.False(rows.Next())
		s.NoError(rows.Close())
		require.NoError(tx.Commit())
		s.NoError(st.Close())
		rows, err = s.conn.Query(tc.query2)
		require.NoError(err)
		v, err := scanValues(rows, tc.expected[0])
		s.NoError(rows.Close())
		require.NoError(err)
		s.Equal(tc.expected, v)
	}
}

func (s *stmtSuite) TestExecMultiRollback() {
	require := s.Require()
	tx, err := s.conn.Begin()
	require.NoError(err)
	st, err := tx.Prepare("INSERT INTO data (i64) VALUES (?)")
	require.NoError(err)
	_, err = st.Exec(31)
	require.NoError(err)
	_, err = st.Exec(32)
	require.NoError(err)
	rows, err := s.conn.Query("SELECT i64 FROM data WHERE i64=31")
	s.NoError(err)
	s.False(rows.Next())
	s.NoError(rows.Close())
	require.NoError(tx.Rollback())
	s.NoError(st.Close())
	rows, err = s.conn.Query("SELECT i64 FROM data WHERE i64>30")
	require.NoError(err)
	s.False(rows.Next())
	s.NoError(rows.Close())
}

func (s *stmtSuite) TestExecMultiInterrupt() {
	require := s.Require()
	tx, err := s.conn.Begin()
	require.NoError(err)
	st, err := tx.Prepare("INSERT INTO data (i64) VALUES (?)")
	require.NoError(err)
	st2, err := tx.Prepare("INSERT INTO data (i64) VALUES (?)")
	require.NoError(err)
	_, err = st.Exec(31)
	require.NoError(err)
	_, err = st.Exec(32)
	require.NoError(err)
	rows, err := s.conn.Query("SELECT i64 FROM data WHERE i64=31")
	s.NoError(err)
	s.False(rows.Next())
	s.NoError(rows.Close())
	require.NoError(st.Close())
	require.NoError(tx.Commit())
	require.NoError(st2.Close())
	rows, err = s.conn.Query("SELECT i64 FROM data WHERE i64>30")
	require.NoError(err)
	s.False(rows.Next())
	s.NoError(rows.Close())
}

func (s *stmtSuite) TestFixDoubleInterpolateInStmt() {
	require := s.Require()
	tx, err := s.conn.Begin()
	require.NoError(err)
	st, err := tx.Prepare("INSERT INTO data (s, s2) VALUES (?, ?)")
	require.NoError(err)
	args := []interface{}{"'", "?"}
	_, err = st.Exec(args...)
	require.NoError(err)
	require.NoError(tx.Commit())
	require.NoError(st.Close())
	rows, err := s.conn.Query("SELECT s, s2 FROM data WHERE s='\\'' AND s2='?'")
	require.NoError(err)
	v, err := scanValues(rows, args)
	if s.NoError(err) {
		s.Equal([][]interface{}{args}, v)
	}
	s.NoError(rows.Close())
}

func TestStmt(t *testing.T) {
	suite.Run(t, new(stmtSuite))
}

package clickhouse

import (
	"math"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

func TestParseData(t *testing.T) {
	type testCase struct {
		name          string
		inputtype     string
		inputopt      *DataParserOptions
		inputdata     string
		output        interface{}
		failParseDesc bool
		failNewParser bool
		failParseData bool
	}

	losAngeles, err := time.LoadLocation("America/Los_Angeles")
	if err != nil {
		t.Fatalf("failed to load time zone America/Los_Angeles: %v", err)
	}
	moscow, err := time.LoadLocation("Europe/Moscow")
	if err != nil {
		t.Fatalf("failed to load time zone Europe/Moscow: %v", err)
	}
	utc := time.UTC

	testCases := []*testCase{
		{
			name:      "nullable string",
			inputtype: "Nullable(String)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable empty string",
			inputtype: "Nullable(String)",
			inputdata: "",
			output:    "",
		},
		{
			name:      "nullable int not null",
			inputtype: "Nullable(UInt64)",
			inputdata: "655",
			output:    uint64(655),
		},
		{
			name:      "string",
			inputtype: "String",
			inputdata: "hello world",
			output:    "hello world",
		},
		{
			name:      "fixed string",
			inputtype: "FixedString(10)",
			inputdata: `hello\0\0\0\0\0`,
			output:    "hello\x00\x00\x00\x00\x00",
		},
		{
			name:      "string with escaping",
			inputtype: "String",
			inputdata: `hello \'world`,
			output:    "hello 'world",
		},
		{
			name:          "string with incorrect escaping",
			inputtype:     "String",
			inputdata:     `hello world\`,
			failParseData: true,
		},
		{
			name:      "int",
			inputtype: "UInt64",
			inputdata: "123",
			output:    uint64(123),
		},
		{
			name:      "float",
			inputtype: "Float32",
			inputdata: "-inf",
			output:    float32(math.Inf(-1)),
		},
		{
			name:      "decimal",
			inputtype: "Decimal(9,4)",
			inputdata: "123",
			output:    "123",
		},
		{
			name:      "date",
			inputtype: "Date",
			inputdata: "2018-01-02",
			output:    time.Date(2018, 1, 2, 0, 0, 0, 0, time.UTC),
		},
		{
			name:      "zero date",
			inputtype: "Date",
			inputdata: "0000-00-00",
			output:    time.Time{},
		},
		{
			name:      "with special timezone",
			inputtype: "Date",
			inputdata: "2019-06-29",
			inputopt: &DataParserOptions{
				Location: losAngeles,
			},
			output: time.Date(2019, 6, 29, 0, 0, 0, 0, losAngeles),
		},
		{
			name:      "enum",
			inputtype: "Enum8('hello' = 1, 'world' = 2)",
			inputdata: "hello",
			output:    "hello",
		},
		{
			name:      "uuid",
			inputtype: "UUID",
			inputdata: "c79a9747-7cef-4b11-8177-380f7ed462a4",
			output:    "c79a9747-7cef-4b11-8177-380f7ed462a4",
		},
		{
			name:      "datetime, without options and argument",
			inputtype: "DateTime",
			inputdata: "2018-01-02 12:34:56",
			output:    time.Date(2018, 1, 2, 12, 34, 56, 0, time.UTC),
		},
		{
			name:      "datetime, with argument",
			inputtype: "DateTime('America/Los_Angeles')",
			inputdata: "2018-01-02 12:34:56",
			output:    time.Date(2018, 1, 2, 12, 34, 56, 0, losAngeles),
		},
		{
			name:      "datetime with argument, but location nil",
			inputtype: "DateTime('America/Los_Angeles')",
			inputdata: "2018-01-02 12:34:56",
			inputopt: &DataParserOptions{
				Location: nil,
			},
			output: time.Date(2018, 1, 2, 12, 34, 56, 0, losAngeles),
		},
		{
			name:      "datetime without argument, but use location",
			inputtype: "DateTime",
			inputdata: "2018-01-02 12:34:56",
			inputopt: &DataParserOptions{
				Location: moscow,
			},
			output: time.Date(2018, 1, 2, 12, 34, 56, 0, moscow),
		},
		{
			name:      "datetime with argument and location, ingnore argument",
			inputtype: "DateTime('America/Los_Angeles')",
			inputdata: "2018-01-02 12:34:56",
			inputopt: &DataParserOptions{
				Location: moscow,
			},
			output: time.Date(2018, 1, 2, 12, 34, 56, 0, moscow),
		},
		{
			name:      "datetime with argument and location, prefer argument",
			inputtype: "DateTime('America/Los_Angeles')",
			inputdata: "2018-01-02 12:34:56",
			inputopt: &DataParserOptions{
				Location:      moscow,
				UseDBLocation: true,
			},
			output: time.Date(2018, 1, 2, 12, 34, 56, 0, losAngeles),
		},
		{
			name:          "datetime in nowhere",
			inputtype:     "DateTime('Nowhere')",
			inputdata:     "2018-01-02 12:34:56",
			failNewParser: true,
		},
		{
			name:      "zero datetime",
			inputtype: "DateTime",
			inputdata: "0000-00-00 00:00:00",
			output:    time.Time{},
		},
		{
			name:          "short datetime",
			inputtype:     "DateTime",
			inputdata:     "000-00-00 00:00:00",
			output:        time.Time{},
			failParseData: true,
		},
		{
			name:          "malformed datetime",
			inputtype:     "DateTime",
			inputdata:     "a000-00-00 00:00:00",
			output:        time.Time{},
			failParseData: true,
		},
		{
			name:      "DateTime64: correct",
			inputtype: "DateTime64(3, 'UTC')",
			inputdata: "2021-12-07 00:00:00.000",
			output:    time.Date(2021, 12, 7, 0, 0, 0, 0, utc),
		},
		{
			name:      "DateTime64: in Moscow with precision 6",
			inputtype: "DateTime64(6, 'Europe/Moscow')",
			inputdata: "2018-01-02 12:34:56.789012",
			output:    time.Date(2018, 1, 2, 12, 34, 56, 789012000, moscow),
		},
		{
			name:      "DateTime64: in Moscow with precision 3",
			inputtype: "DateTime64(3, 'Europe/Moscow')",
			inputdata: "2018-01-02 12:34:56.789012",
			output:    time.Date(2018, 1, 2, 12, 34, 56, 789000000, moscow),
		},
		{
			name:          "DateTime64: incorrect",
			inputtype:     "DateTime64(4, 'Europe/Moscow')",
			inputdata:     "2018-01-02 12:34:56.789",
			failParseData: true,
		},
		{
			name:      "DateTime64: zero",
			inputtype: "DateTime64(3, 'Europe/Moscow')",
			inputdata: "0000-00-00 00:00:00.000",
			output:    time.Time{},
		},
		{
			name:          "DateTime64: no tick size",
			inputtype:     "DateTime64",
			inputdata:     "2018-01-02 12:34:56.789",
			failNewParser: true,
		},
		{
			name:          "DateTime64: no tick size",
			inputtype:     "DateTime64(3, 'Nowhere')",
			inputdata:     "2018-01-02 12:34:56.789",
			failNewParser: true,
		},
		{
			name:      "DateTime64: with argument and location, prefer argument",
			inputtype: "DateTime64(3, 'America/Los_Angeles')",
			inputdata: "2018-01-02 12:34:56.789",
			inputopt: &DataParserOptions{
				Location:      moscow,
				UseDBLocation: true,
			},
			output: time.Date(2018, 1, 2, 12, 34, 56, 789000000, losAngeles),
		},
		{
			name:      "DateTime64: with argument and location, prefer argument",
			inputtype: "DateTime64(3)",
			inputdata: "2018-01-02 12:34:56.789",
			inputopt: &DataParserOptions{
				Location:      moscow,
				UseDBLocation: true,
			},
			output: time.Date(2018, 1, 2, 12, 34, 56, 789000000, moscow),
		},
		{
			name:      "tuple",
			inputtype: "Tuple(String, Float64, Int16, UInt16, Int64)",
			inputdata: "('hello world',32.1,-1,2,3)",
			output: struct {
				Field0 string
				Field1 float64
				Field2 int16
				Field3 uint16
				Field4 int64
			}{"hello world", 32.1, -1, 2, 3},
		},
		{
			name:      "array of strings",
			inputtype: "Array(String)",
			inputdata: `['hello world\',','goodbye galaxy']`,
			output:    []string{"hello world',", "goodbye galaxy"},
		},
		{
			name:          "array of unquoted strings",
			inputtype:     "Array(String)",
			inputdata:     "[hello,world]",
			failParseData: true,
		},
		{
			name:          "array with unfinished quoted string",
			inputtype:     "Array(String)",
			inputdata:     "['hello','world]",
			failParseData: true,
		},
		{
			name:      "array of ints",
			inputtype: "Array(UInt64)",
			inputdata: "[1,2,3]",
			output:    []uint64{1, 2, 3},
		},
		{
			name:      "array of dates",
			inputtype: "Array(Date)",
			inputdata: "['2018-01-02','0000-00-00']",
			output: []time.Time{
				time.Date(2018, 1, 2, 0, 0, 0, 0, time.UTC),
				{},
			},
		},
		{
			name:      "empty array of ints",
			inputtype: "Array(Int8)",
			inputdata: "[]",
			output:    []int8{},
		},
		{
			name:      "empty array of nothing",
			inputtype: "Array(Nothing)",
			inputdata: "[]",
			output:    []struct{}{},
		},
		{
			name:      "array of tuples",
			inputtype: "Array(Tuple(String, Float32))",
			inputdata: "[('hello world',32.1),('goodbye galaxy',42.0)]",
			output: []struct {
				Field0 string
				Field1 float32
			}{
				{
					"hello world",
					float32(32.1),
				},
				{
					"goodbye galaxy",
					float32(42.0),
				},
			},
		},
		{
			name:          "malformed array element",
			inputtype:     "Array(UInt8)",
			inputdata:     "[1,2,'3']",
			failParseData: true,
		},
		{
			name:          "array without left bracket",
			inputtype:     "Array(Int8)",
			inputdata:     "1,2,3]",
			failParseData: true,
		},
		{
			name:          "array without right bracket",
			inputtype:     "Array(UInt64)",
			inputdata:     "[1,2,3",
			failParseData: true,
		},
		{
			name:          "wrong character between tuple elements",
			inputtype:     "Tuple(String, String)",
			inputdata:     "('hello'.'world')",
			failParseData: true,
		},
		{
			name:          "malformed tuple element",
			inputtype:     "Tuple(UInt32, Int32)",
			inputdata:     "(1,'2')",
			failParseData: true,
		},
		{
			name:          "tuple without left paren",
			inputtype:     "Tuple(Int8, Int8)",
			inputdata:     "1,2)",
			failParseData: true,
		},
		{
			name:          "tuple without right paren",
			inputtype:     "Tuple(UInt8, Int8)",
			inputdata:     "(1,2",
			failParseData: true,
		},
		{
			name:      "low cardinality string",
			inputtype: "LowCardinality(String)",
			inputdata: "hello",
			output:    "hello",
		},
		{
			name:      "low cardinality string with escaping",
			inputtype: "LowCardinality(String)",
			inputdata: `hello \'world`,
			output:    "hello 'world",
		},
		{
			name:          "low cardinality string with incorrect escaping",
			inputtype:     "LowCardinality(String)",
			inputdata:     `hello world\`,
			failParseData: true,
		},
		{
			name:      "low cardinality UInt64",
			inputtype: "LowCardinality(UInt64)",
			inputdata: "123",
			output:    uint64(123),
		},
		{
			name:      "simple aggregate function of uint64",
			inputtype: "SimpleAggregateFunction(max, UInt64)",
			inputdata: "123",
			output:    uint64(123),
		},
		{
			name:      "simple aggregate function of mixed tuple",
			inputtype: "SimpleAggregateFunction(avg, Tuple(String, UInt64))",
			inputdata: "('abc',123)",
			output: struct {
				Field0 string
				Field1 uint64
			}{"abc", uint64(123)},
		},
		{
			name:      "ipv4",
			inputtype: "IPv4",
			inputdata: "127.0.0.1",
			output:    "127.0.0.1",
		},
		{
			name:      "ipv6",
			inputtype: "IPv6",
			inputdata: "2a02:aa08:e000:3100::2",
			output:    "2a02:aa08:e000:3100::2",
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(tt *testing.T) {
			desc, err := ParseTypeDesc(tc.inputtype)
			if tc.failParseDesc {
				assert.Error(tt, err)
				return
			}
			if !assert.NoError(tt, err) {
				return
			}

			parser, err := newDataParser(desc, false, tc.inputopt)
			if tc.failNewParser {
				assert.Error(tt, err)
				return
			}
			if !assert.NoError(tt, err) {
				return
			}

			output, err := parser.Parse(strings.NewReader(tc.inputdata))
			if tc.failParseData {
				assert.Error(tt, err)
				return
			}
			if !assert.NoError(tt, err) {
				return
			}

			assert.Equal(tt, tc.output, output)
		})
	}
}

func TestParseDataNewNullableArray(t *testing.T) {
	type testCase struct {
		name          string
		inputtype     string
		inputopt      *DataParserOptions
		inputdata     string
		output        interface{}
		failParseDesc bool
		failNewParser bool
		failParseData bool
	}

	losAngeles, err := time.LoadLocation("America/Los_Angeles")
	if err != nil {
		t.Fatalf("failed to load time zone America/Los_Angeles: %v", err)
	}
	moscow, err := time.LoadLocation("Europe/Moscow")
	if err != nil {
		t.Fatalf("failed to load time zone Europe/Moscow: %v", err)
	}

	t.Log(losAngeles, moscow)

	testCases := []*testCase{
		{
			name:      "array of nullable null String",
			inputtype: "Array(Nullable(String))",
			inputdata: `['ss','\N','dd','ff']`,
			output:    []string{"ss", "dd", "ff"},
		},
		{
			name:      "array(nullable(uuid))",
			inputtype: "Array(Nullable(UUID))",
			inputdata: `['c79a9747-7cef-4b11-8177-380f7ed462a4','\N','00000000-0000-0000-0000-000000000000']`,
			output:    []string{"c79a9747-7cef-4b11-8177-380f7ed462a4", "00000000-0000-0000-0000-000000000000"},
		},
		{
			name:      "array of nullable null UInt64",
			inputtype: "Array(Nullable(UInt64))",
			inputdata: `[1,\N,5,9]`,
			output:    []uint64{1, 5, 9},
		},
		{
			name:      "array of nullable null UInt16",
			inputtype: "Array(Nullable(UInt16))",
			inputdata: `[1,2,\N]`,
			output:    []uint16{1, 2},
		},
		{
			name:          "malformed array(nullable(date))",
			inputtype:     "Array(Nullable(Date))",
			inputdata:     `['a000-00-00 00:00:00', '\N']`,
			output:        []time.Time{{}},
			failParseData: true,
		},
		{
			name:      "array of nullable null Float64",
			inputtype: "Array(Nullable(Float64))",
			inputdata: `[1.9,\N,5.3,9.9]`,
			output:    []float64{1.9, 5.3, 9.9},
		},
		{
			name:      "array(nullable(datetime)), without options and argument",
			inputtype: "Array(Nullable(DateTime))",
			inputdata: `['2018-01-02 12:34:56','\N','0000-00-00 00:00:00']`,
			output: []time.Time{
				time.Date(2018, 1, 2, 12, 34, 56, 0, time.UTC),
				{},
			},
		},
		{
			name:      "nullable null string",
			inputtype: "Nullable(String)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable null UInt64",
			inputtype: "Nullable(UInt64)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable null decimal",
			inputtype: "Nullable(Decimal)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable null datetime",
			inputtype: "Nullable(DateTime)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable null date",
			inputtype: "Nullable(Date)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable not null datetime",
			inputtype: "Nullable(DateTime)",
			inputdata: "2018-01-02 12:34:56",
			output:    time.Date(2018, 1, 2, 12, 34, 56, 0, time.UTC),
		},
		{
			name:      "nullable not null date",
			inputtype: "Nullable(Date)",
			inputdata: "2018-01-02",
			output:    time.Date(2018, 1, 2, 0, 0, 0, 0, time.UTC),
		},
		{
			name:      "nullable null enum",
			inputtype: "Nullable(Enum8('hello' = 1, 'world' = 2))",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable null uuid",
			inputtype: "Nullable(UUID)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable null Date",
			inputtype: "Nullable(Date)",
			inputdata: `\N`,
			output:    nil,
		},
		{
			name:      "nullable(decimal)",
			inputtype: "Nullable(Decimal(9,4))",
			inputdata: "123",
			output:    "123",
		},
		{
			name:      "array(nullable(decimal))",
			inputtype: "Array(Nullable(Decimal(9,4)))",
			inputdata: "['123','555.6']",
			output:    []string{"123", "555.6"},
		},
		{
			name:      "nullable(enum)",
			inputtype: "Nullable(Enum8('hello' = 1, 'world' = 2))",
